{
  "name": "Binder MK 56 气候试验箱",
  "name_en": "Binder MK 56 Climate Chamber",
  "manufacturer": "Binder",
  "description": "这是一台实验室气候试验箱，用于在受控箱体环境中对样品进行温度相关的稳定性测试、环境模拟和常规培养/存放实验。设备通过箱门装载样品，并可查看运行模式与箱门状态。",
  "description_en": "This is a laboratory climate chamber used to expose samples to a controlled chamber environment for temperature-related stability testing, environmental simulation, and routine incubation or storage experiments. Samples are loaded through the chamber door, and the device provides operating-mode and door-status information.",
  "tag_hints": [
    "climate chamber",
    "environmental testing",
    "temperature control",
    "sample stability testing",
    "laboratory incubation",
    "RS-422 serial communication"
  ],
  "actions": [
    {
      "action_name": "auto-get_door_open",
      "description": "获取箱门是否打开",
      "description_en": "Get whether the chamber door is open"
    },
    {
      "action_name": "auto-get_mode",
      "description": "获取设备运行模式",
      "description_en": "Get the operating mode"
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置箱内目标温度",
      "description_en": "Set the chamber target temperature"
    }
  ]
}

